#include "stdafx.h"#include "HcdElementBase.h"struct STRIG_P{#include "PrivateVars/TRIG.h"};class KTRIG : public KHcdElementBase  , protected STRIG_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _TRIG("TRIG", KTRIG::Create);IHcdElement *KTRIG::Create(){  return new KTRIG;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KTRIG, 3 )void KTRIG::InitParm(){#include "PrivateVars/TRIG.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KTRIG::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KTRIG::StepCalc( SStepCalcParams &params ){  if( !prevIn && INL0 )    OUT = 1;  else    OUT = 0;  prevIn = INL0;}